type Flight = Shared<BoxFuture<'static, Result<Value, Arc<Error>>>>;
impl Coalescer {
    async fn load(&self, key: String, src: Arc<Source>) -> Result<Value, Arc<Error>> {
        let fut = {
            let mut m = self.flights.lock().await;        // never held across await
            if let Some(f) = m.get(&key) { return f.clone().await; }   // join it
            let f = async move { src.read(&key).await.map_err(Arc::new) }.boxed().shared();
            m.insert(key.clone(), f.clone());             // announce the flight
            f
        };
        let out = fut.await;                              // shared value or error
        self.flights.lock().await.remove(&key);           // forget on completion
        out
    }
}
